class BookManagement:
    MAGIC_NUMBER_ZERO = 0

    def __init__(self):
        self._inventory = {}

    def _is_book_in_inventory(self, title):
        return title in self._inventory

    def _get_book_quantity(self, title):
        return self._inventory.get(title, 0)

    def _set_book_quantity(self, title, quantity):
        if quantity <= 0:
            self._remove_book_from_inventory(title)
        else:
            self._inventory[title] = quantity

    def _remove_book_from_inventory(self, title):
        if title in self._inventory:
            del self._inventory[title]

    def add_book(self, title, quantity=1):
        current_quantity = self._get_book_quantity(title)
        new_quantity = current_quantity + quantity
        self._set_book_quantity(title, new_quantity)

    def remove_book(self, title, quantity):
        current_quantity = self._get_book_quantity(title)
        if current_quantity < quantity:
            raise ValueError(f"Cannot remove {quantity} copies of '{title}'; only {current_quantity} available.")
        new_quantity = current_quantity - quantity
        self._set_book_quantity(title, new_quantity)

    def view_inventory(self):
        return dict(self._inventory)

    def view_book_quantity(self, title):
        return self._get_book_quantity(title)
